#include <Arduino.h>
#include <Servo.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int BUTTON_PIN = 2;  
const int SERVO1_PIN = 3;  
const int SERVO2_PIN = 4;  
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000, 
};
int currentNumber = 0;
Servo servo1;
Servo servo2;

void setup();
void loop();
void displayNumber(int number);
void moveServos(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP); 
  servo1.attach(SERVO1_PIN);
  servo2.attach(SERVO2_PIN);
  displayNumber(currentNumber);
  moveServos(currentNumber);
}
void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    delay(150); 
    if (digitalRead(BUTTON_PIN) == LOW) {
      currentNumber++;
      if (currentNumber > 9) {
        currentNumber = 0;
      }
      displayNumber(currentNumber);
      moveServos(currentNumber);
      while (digitalRead(BUTTON_PIN) == LOW); 
    }
  }
}
void displayNumber(int number) {
  byte code = segmentCodes[number];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, code);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void moveServos(int number) {
  if (number % 2 == 0) {
    servo1.write(0);
    servo2.write(0);
  } else {
    servo1.write(90);
    servo2.write(90);
  }
}
